# Generated by GitHub Copilot - Oct-26-2026
import unittest
from datetime import date, timedelta
from typing import Any

from health_dashboard import build_dashboard_payload, build_training_outlook


class TrainingOutlookTests(unittest.TestCase):
    """Verify freshness, completeness, caution directions, and independent sleep grouping."""

    def setUp(self) -> None:
        """Provide six comparable synthetic metrics on one date."""
        self.today = date(2026, 10, 26)
        self.metrics: dict[str, dict[str, Any]] = {
            key: {
                "label": key,
                "status": "within_usual",
                "latest": {"date": self.today.isoformat(), "value": 50},
                "usualRange28": [40, 60],
                "unit": "score",
            }
            for key in ("hrv", "sleep", "sleepScore", "restingHeartRate", "stress", "bodyBattery")
        }

    def test_complete_readings_produce_outlook_not_numeric_score(self) -> None:
        """Expose completeness and provenance rather than implying a validated Garmin score."""
        result = build_training_outlook(self.metrics, self.today)
        self.assertEqual(result["status"], "close_to_usual")
        self.assertEqual(result["availableGroups"], 5)
        self.assertEqual(result["missingGroups"], [])
        self.assertEqual(result["asOfDate"], self.today.isoformat())
        self.assertFalse(result["activityAvailable"])
        self.assertNotIn("score", result)
        self.assertIn("not Garmin Training Readiness", result["disclaimer"])

    def test_same_day_sleep_and_two_other_groups_are_required(self) -> None:
        """Insufficient evidence cannot reassure the user even with valid individual readings."""
        for keys in (("sleep", "sleepScore"), ("hrv", "sleep"), ("hrv", "restingHeartRate", "stress")):
            with self.subTest(keys=keys):
                subset = {key: self.metrics[key] for key in keys}
                self.assertEqual(build_training_outlook(subset, self.today)["status"], "insufficient_data")
        subset = {key: self.metrics[key] for key in ("sleep", "hrv", "stress")}
        self.assertEqual(build_training_outlook(subset, self.today)["status"], "close_to_usual")

    def test_sleep_duration_and_score_count_as_one_caution(self) -> None:
        """Two related sleep values must not become two independent warning groups."""
        self.metrics["sleep"]["status"] = "below_usual"
        self.metrics["sleepScore"]["status"] = "below_usual"
        result = build_training_outlook(self.metrics, self.today)
        self.assertEqual(result["status"], "flexible")
        self.assertEqual(len(result["reasons"]), 2)
        self.metrics["hrv"]["status"] = "below_usual"
        self.assertEqual(build_training_outlook(self.metrics, self.today)["status"], "easier_day")

    def test_display_colors_do_not_determine_caution(self) -> None:
        """Green high resting heart rate still cautions; red low stress need not."""
        self.metrics["restingHeartRate"]["status"] = "above_usual"
        self.assertEqual(build_training_outlook(self.metrics, self.today)["status"], "flexible")
        self.metrics["restingHeartRate"]["status"] = "below_usual"
        self.metrics["stress"]["status"] = "below_usual"
        for key in ("hrv", "sleep", "sleepScore", "bodyBattery"):
            self.metrics[key]["status"] = "above_usual"
        self.assertEqual(build_training_outlook(self.metrics, self.today)["status"], "close_to_usual")

    def test_old_future_and_missing_readings_do_not_count(self) -> None:
        """Never turn stale or missing measurements into today's readiness."""
        for metric in self.metrics.values():
            metric["latest"]["date"] = (self.today - timedelta(days=2)).isoformat()
        result = build_training_outlook(self.metrics, self.today)
        self.assertEqual(result["status"], "insufficient_data")
        self.assertEqual(result["availableGroups"], 0)
        self.assertIsNone(result["asOfDate"])
        for metric in self.metrics.values():
            metric["latest"]["date"] = (self.today + timedelta(days=1)).isoformat()
        self.assertEqual(build_training_outlook(self.metrics, self.today)["availableGroups"], 0)
        for metric in self.metrics.values():
            metric["latest"] = None
        self.assertEqual(build_training_outlook(self.metrics, self.today)["status"], "insufficient_data")

    def test_yesterday_is_dated_and_not_combined_with_today(self) -> None:
        """Use a single latest date, not a favorable mixture of dates."""
        yesterday = (self.today - timedelta(days=1)).isoformat()
        for metric in self.metrics.values():
            metric["latest"]["date"] = yesterday
        self.assertEqual(build_training_outlook(self.metrics, self.today)["asOfDate"], yesterday)
        self.metrics["stress"]["latest"]["date"] = self.today.isoformat()
        result = build_training_outlook(self.metrics, self.today)
        self.assertEqual(result["availableGroups"], 1)
        self.assertEqual(result["status"], "insufficient_data")

    def test_uncomparable_metrics_do_not_inflate_completeness(self) -> None:
        """Readings without enough baseline history do not establish an outlook."""
        for metric in self.metrics.values():
            metric["status"] = "insufficient_history"
        self.assertEqual(build_training_outlook(self.metrics, self.today)["availableGroups"], 0)

    def test_volume_cautions_only_when_activity_history_is_available(self) -> None:
        """Missing activity must not be interpreted as zero load or a real volume flag."""
        context = {"available": True, "volumeStatus": "well_above_recent"}
        result = build_training_outlook(self.metrics, self.today, context)
        self.assertEqual(result["status"], "easier_day")
        self.assertTrue(result["activityAvailable"])
        self.assertIn("Recorded exercise", result["reasons"][0])
        context["available"] = False
        self.assertEqual(build_training_outlook(self.metrics, self.today, context)["status"], "close_to_usual")
        self.assertEqual(build_training_outlook({}, self.today, context)["status"], "insufficient_data")

    def test_payload_includes_explicit_unavailable_outlook(self) -> None:
        """Wire the estimator into the existing API payload without inventing measurements."""
        payload = build_dashboard_payload({}, {}, self.today, self.today)
        self.assertEqual(payload["trainingOutlook"]["status"], "insufficient_data")
        self.assertEqual(payload["trainingOutlook"]["totalGroups"], 5)


if __name__ == "__main__":
    unittest.main()
